def solve(N, points):
    points.sort()
    x_coords, y_coords = zip(*points)

    def binpow(a, n):
        result = 1
        while n > 0:
            if n % 2 == 1:
                result = (result * a) % MOD
            a = (a * a) % MOD
            n //= 2
        return result

    total_sum = 0
    for i in range(1 << N):
        min_x = max_x = min_y = max_y = None
        for j in range(N):
            if i & (1 << j):
                if min_x is None or x_coords[j] < min_x:
                    min_x = x_coords[j]
                if max_x is None or x_coords[j] > max_x:
                    max_x = x_coords[j]
