def sum_of_f(n, points):
    points.sort()
    x_coords, y_coords = zip(*points)
    x_count, y_count = [0] * n, [0] * n

    for i in range(1, n):
        if x_coords[i] != x_coords[i - 1]:
            x_count[i] += x_count[i - 1] + 1
        else:
            x_count[i] = x_count[i - 1]

    for i in range(1, n):
        if y_coords[i] != y_coords[i - 1]:
            y_count[i] += y_count[i - 1] + 1
        else:
            y_count[i] = y_count[i - 1]

    result = 0
    for i in range(n):
        result += (x_count[i] + 1) * (y_count[i] + 1)
        result %= MOD

    return result

